def parse_bool(value, default=False):
    """رشته را به Boolean تبدیل می‌کند."""
    if value is None:
        return default
    return value.lower() in ("true", "1", "yes", "on")


class BookListView(generics.ListAPIView):
    def get_queryset(self):
        qs = Book.objects.all()
        in_stock = parse_bool(self.request.query_params.get("in_stock"))
        if in_stock:
            qs = qs.filter(stock__gt=0)
        return qs

