from datetime import date, datetime


class BookListView(generics.ListAPIView):
    def get_queryset(self):
        qs = Book.objects.all()
        params = self.request.query_params

        after = params.get("created_after")
        if after:
            try:
                qs = qs.filter(created_at__date__gte=date.fromisoformat(after))
            except ValueError:
                raise ValidationError({"created_after": "فرمت تاریخ نامعتبر (YYYY-MM-DD)."})

        before = params.get("created_before")
        if before:
            try:
                qs = qs.filter(created_at__date__lte=date.fromisoformat(before))
            except ValueError:
                raise ValidationError({"created_before": "فرمت تاریخ نامعتبر."})

        return qs

from rest_framework import serializers


class BookListQuerySerializer(serializers.Serializer):
    category = serializers.SlugField(required=False)
    min_price = serializers.DecimalField(
        max_digits=8, decimal_places=2, required=False, min_value=0,
    )
    max_price = serializers.DecimalField(
        max_digits=8, decimal_places=2, required=False, min_value=0,
    )
    in_stock = serializers.BooleanField(required=False)
    created_after = serializers.DateField(required=False)
    ordering = serializers.ChoiceField(
        choices=["price", "-price", "title", "-created_at"],
        required=False,
        default="-created_at",
    )


class BookListView(generics.ListAPIView):
    serializer_class = BookSerializer

    def get_queryset(self):
        # اعتبارسنجی پارامترها
        query = BookListQuerySerializer(data=self.request.query_params)
        query.is_valid(raise_exception=True)
        params = query.validated_data

        qs = Book.objects.all()
        if "category" in params:
            qs = qs.filter(category__slug=params["category"])
        if "min_price" in params:
            qs = qs.filter(price__gte=params["min_price"])
        if "max_price" in params:
            qs = qs.filter(price__lte=params["max_price"])
        if params.get("in_stock"):
            qs = qs.filter(stock__gt=0)
        if "created_after" in params:
            qs = qs.filter(created_at__date__gte=params["created_after"])

        return qs.order_by(params["ordering"])

