from datetime import date
from decimal import Decimal, InvalidOperation
from rest_framework import generics
from rest_framework.exceptions import ValidationError


class ProductListView(generics.ListAPIView):
    serializer_class = ProductSerializer

    def get_queryset(self):
        qs = Product.objects.select_related("category", "brand")
        params = self.request.query_params

        category = params.get("category")
        if category:
            qs = qs.filter(category__slug=category)

        brand = params.get("brand")
        if brand:
            qs = qs.filter(brand__slug=brand)

        min_price = params.get("min_price")
        if min_price:
            try:
                qs = qs.filter(price__gte=Decimal(min_price))
            except (InvalidOperation, ValueError):
                raise ValidationError({"min_price": "عدد نامعتبر."})

        max_price = params.get("max_price")
        if max_price:
            try:
                qs = qs.filter(price__lte=Decimal(max_price))
            except (InvalidOperation, ValueError):
                raise ValidationError({"max_price": "عدد نامعتبر."})

        in_stock = params.get("in_stock")
        if in_stock is not None:
            if in_stock.lower() in ("true", "1", "yes"):
                qs = qs.filter(stock__gt=0)
            elif in_stock.lower() in ("false", "0", "no"):
                qs = qs.filter(stock=0)
            else:
                raise ValidationError({"in_stock": "مقدار Boolean نامعتبر."})

        created_after = params.get("created_after")
        if created_after:
            try:
                qs = qs.filter(created_at__date__gte=date.fromisoformat(created_after))
            except ValueError:
                raise ValidationError({"created_after": "فرمت تاریخ نامعتبر (YYYY-MM-DD)."})

        return qs
